import{_ as e,o as r,c as o,ae as a}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"乾淨架構與業務規格中樞","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/clean-architecture.md","filePath":"architecture/clean-architecture.md"}'),c={name:"architecture/clean-architecture.md"};function s(d,t,n,i,h,l){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="乾淨架構與業務規格中樞" tabindex="-1">乾淨架構與業務規格中樞 <a class="header-anchor" href="#乾淨架構與業務規格中樞" aria-label="Permalink to &quot;乾淨架構與業務規格中樞&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本專案朝向 <strong>乾淨架構（Clean Architecture）</strong>，並以 <strong>業務規格（docs/product/*）為專案中樞</strong>：所有功能與資料流皆可追溯到規格，依賴方向由外而內，業務邏輯不依賴框架與 UI。</p><hr><h2 id="業務規格做專案中樞" tabindex="-1">業務規格做專案中樞 <a class="header-anchor" href="#業務規格做專案中樞" aria-label="Permalink to &quot;業務規格做專案中樞&quot;">​</a></h2><ul><li><strong>中樞</strong>：<code>docs/product/</code> 內文件描述現況規格（業務流程、領域模型、API 行為、資料結構）。</li><li><strong>原則</strong>：新功能或 API 應先有對應的 product 文件或 ticket 描述；實作時 Contract、Mock、Test、UI 皆對齊該規格。</li><li><strong>對照</strong>：docs/architecture、docs/conventions 為架構與技術參考；docs/product 為「做什麼」的單一來源。</li></ul><table tabindex="0"><thead><tr><th>規格類型</th><th>位置</th><th>用途</th></tr></thead><tbody><tr><td>業務／領域</td><td>docs/product/*</td><td>專案中樞；功能一覽、領域模型、API 規格</td></tr><tr><td>架構／流程</td><td>docs/architecture、docs/conventions</td><td>怎麼實作、怎麼協作</td></tr></tbody></table><hr><h2 id="乾淨架構層級對應-本專案" tabindex="-1">乾淨架構層級對應（本專案） <a class="header-anchor" href="#乾淨架構層級對應-本專案" aria-label="Permalink to &quot;乾淨架構層級對應（本專案）&quot;">​</a></h2><p>依賴方向：<strong>外層依賴內層</strong>，內層不認識外層。</p><table tabindex="0"><thead><tr><th>層級（由內而外）</th><th>本專案對應</th><th>說明</th></tr></thead><tbody><tr><td><strong>Entities / 領域</strong></td><td>docs/product/*、<code>app/shared/types/_</code>、契約中的 entity schema</td><td>領域模型與共用型別；規格寫在 product，型別與 schema 為可執行表達</td></tr><tr><td><strong>Use Cases / 應用</strong></td><td><code>app/features/*/*.server.ts</code>、<code>app/shared/contracts/*</code>、<code>app/services/*</code></td><td>業務流程與資料契約；輸入輸出由 Zod schema 定義</td></tr><tr><td><strong>Interface Adapters</strong></td><td><code>app/test/handlers.ts</code>（MSW）、<code>app/shared/api</code>、<code>app/routes/api.*</code></td><td>將外部請求轉成 use case 可用的格式；契約為介面</td></tr><tr><td><strong>Frameworks &amp; UI</strong></td><td><code>app/routes/*</code>、<code>app/components/*</code>、<code>app/features/*/*.hooks.ts</code></td><td>路由與 UI 只協調資料與畫面；不寫業務邏輯</td></tr></tbody></table><hr><h2 id="資料流與規格對齊-spec-→-contract-→-mock-→-test-→-ui" tabindex="-1">資料流與規格對齊（Spec → Contract → Mock → Test → UI） <a class="header-anchor" href="#資料流與規格對齊-spec-→-contract-→-mock-→-test-→-ui" aria-label="Permalink to &quot;資料流與規格對齊（Spec → Contract → Mock → Test → UI）&quot;">​</a></h2><ul><li><strong>Spec</strong>：docs/product/* 或 ticket — 業務範圍、驗收、資料形狀。</li><li><strong>Contract</strong>：<code>app/shared/contracts/</code> — Zod schema，可 runtime 驗證。</li><li><strong>Mock</strong>：<code>app/test/handlers.ts</code> — MSW handler 回傳經 schema parse。</li><li><strong>Test</strong>：依 handler 與 fixture；可先於 UI。</li><li><strong>UI</strong>：僅透過 useFetcher / shared api 打契約路徑，不直接 fetch 硬編碼 URL。</li></ul><p>此流程確保「業務規格為中樞」：從規格到契約到 mock 到 UI 一貫可追溯。</p><hr><h2 id="實務要點" tabindex="-1">實務要點 <a class="header-anchor" href="#實務要點" aria-label="Permalink to &quot;實務要點&quot;">​</a></h2><ol><li><strong>新增功能</strong>：先寫或更新 docs/product/*（或 ticket），再走 Contract → Mock → Test → UI。</li><li><strong>跨模組</strong>：共用邏輯放 <code>app/shared/*</code>，應用層整合放 <code>app/services/*</code>；領域知識以 docs/product 與 shared types 為準。</li><li><strong>Routes</strong>：僅負責協調 loader/action 與 UI，不包含業務判斷；業務在 features/*.server.ts 或 services。</li><li><strong>依賴</strong>：features 與 components 可依賴 shared/contracts；contracts 與 shared/types 不依賴 routes 或 UI。</li></ol><hr><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./../product/overview.html">overview</a>：功能一覽與專案定位</li><li><a href="./data-flow.html">data-flow</a>：契約與請求流</li><li><a href="./../conventions/data-test-driven.html">data-test-driven</a>：Spec→Contract→Mock→Test→UI 流程</li></ul>',21)])])}const g=e(c,[["render",s]]);export{u as __pageData,g as default};
